from __future__ import annotations

def pair_direct(t: float) -> complex:
    return 1 / complex(0.5, t) + 1 / complex(0.5, -t)

def pair_formula(t: float) -> float:
    return 1.0 / (0.25 + t * t)

for t in [0.0, 1.0, 5.0, 14.134725]:
    print(t, pair_direct(t), pair_formula(t))

from __future__ import annotations
from typing import Iterable

def window_harmonic(values: Iterable[float]) -> float:
    return sum(1.0 / (0.25 + t*t) for t in values)

values = [1.0, 2.0, 5.0, 10.0]
for n in range(len(values) + 1):
    total = window_harmonic(values[:n])
    print(n, total, total <= 4*n)

from fractions import Fraction
from typing import Iterable

def ratio(l_value: Fraction, q_value: Fraction) -> Fraction:
    if q_value == 0:
        raise ValueError("q must be nonzero")
    return l_value / q_value

for name, l_value, q_value in [("octave", 4, 2), ("fifth", 3, 2), ("fourth", 4, 3)]:
    print(name, ratio(Fraction(l_value), Fraction(q_value)))

