from __future__ import annotations
from typing import Sequence

def certify(points: Sequence[complex]) -> tuple[complex, float]:
    if not points:
        return 0j, 0.0
    if any(z == 0 for z in points):
        raise ValueError("points must be nonzero")
    delta = min(abs(z) for z in points)
    return sum((1/z for z in points), 0j), len(points)/delta

print(certify([2+1j, 2-1j, 3+4j, 3-4j]))

